package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.*;
/** Authenticated original ore hosts at personally worked chunks; no retrospective terrain classification. */
public final class NativeGeologyEvidence {
 public static final Set<String> HOSTS=Set.of("minecraft:stone","minecraft:deepslate","minecraft:granite","minecraft:diorite","minecraft:andesite","minecraft:tuff");
 private record Area(UUID player,long chunk){}
 private final Map<Area,Set<String>> areas=new HashMap<>();
 public boolean record(UUID player,long chunk,String host){if(!HOSTS.contains(host))return false;var key=new Area(player,chunk);if(!areas.containsKey(key)&&(areas.size()>=8192||areas.keySet().stream().filter(a->a.player().equals(player)).count()>=512))return false;return areas.computeIfAbsent(key,k->new HashSet<>()).add(host);}
 public int count(UUID player){var assigned=new HashMap<String,Long>();for(String host:HOSTS)match(player,host,assigned,new HashSet<>());return assigned.size();}
 private boolean match(UUID player,String host,Map<String,Long> assigned,Set<Long> visited){for(var row:areas.entrySet())if(row.getKey().player().equals(player)&&row.getValue().contains(host)&&visited.add(row.getKey().chunk())){var prior=assigned.entrySet().stream().filter(e->e.getValue()==row.getKey().chunk()).map(Map.Entry::getKey).findFirst().orElse(null);if(prior==null||match(player,prior,assigned,visited)){assigned.put(host,row.getKey().chunk());return true;}}return false;}
 public CompoundTag save(){var root=new CompoundTag();root.putInt("schema",1);var rows=new ListTag();areas.entrySet().stream().sorted(Comparator.comparing(e->e.getKey().player()+":"+e.getKey().chunk())).forEach(e->{var row=new CompoundTag();row.putUUID("player",e.getKey().player());row.putLong("chunk",e.getKey().chunk());var hosts=new ListTag();e.getValue().stream().sorted().forEach(h->hosts.add(StringTag.valueOf(h)));row.put("hosts",hosts);rows.add(row);});root.put("areas",rows);return root;}
 public static NativeGeologyEvidence load(CompoundTag root){if(!root.getAllKeys().equals(Set.of("schema","areas"))||!root.contains("schema",Tag.TAG_INT)||root.getInt("schema")!=1||!(root.get("areas") instanceof ListTag rows)||rows.size()>8192||!rows.isEmpty()&&rows.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Invalid native geological evidence");var result=new NativeGeologyEvidence();for(var value:rows){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("player","chunk","hosts"))||!row.hasUUID("player")||!row.contains("chunk",Tag.TAG_LONG)||!(row.get("hosts") instanceof ListTag hosts)||hosts.isEmpty()||hosts.size()>HOSTS.size()||hosts.getElementType()!=Tag.TAG_STRING||result.areas.containsKey(new Area(row.getUUID("player"),row.getLong("chunk"))))throw new IllegalArgumentException("Invalid geological working area");for(var host:hosts)if(!result.record(row.getUUID("player"),row.getLong("chunk"),host.getAsString()))throw new IllegalArgumentException("Invalid or duplicate geological host");}return result;}
}
